1	/*
2	 * Optional transport boundary.
3	 *
4	 * The capture app does not import system.interconnect and does not require a
5	 * phone or network. A device integration may inject a sender implementing this
6	 * interface in a separately reviewed build. The payload is the same manifest
7	 * and chunk JSON already persisted by system.storage.
8	 */
9	export function createOptionalInterconnectExporter (sender) {
10	  return {
11	    available: Boolean(sender && typeof sender.send === 'function'),
12	    send: function (record, success, fail) {
13	      if (!sender || typeof sender.send !== 'function') {
14	        if (typeof fail === 'function') fail('interconnect_unavailable')
15	        return
16	      }
17	      sender.send({
18	        type: 'bmt_capture_v1',
19	        payload: JSON.stringify(record),
20	        success: success,
21	        fail: fail
22	      })
23	    }
24	  }
25	}
