4	export const FORMAT_VERSION = 'bmt-capture-v1'
5	
6	export function fnv1a32 (text) {
7	  let hash = 2166136261
8	  for (let index = 0; index < text.length; index += 1) {
9	    hash ^= text.charCodeAt(index)
10	    hash = Math.imul(hash, 16777619)
11	  }
12	  return hash >>> 0
13	}
14	
15	export function checksum (value) {
16	  return fnv1a32(typeof value === 'string' ? value : JSON.stringify(value))
17	    .toString(16)
18	    .padStart(8, '0')
19	}
20	
21	export function median (values) {
22	  if (!values.length) return 0
23	  const sorted = values.slice().sort((left, right) => left - right)
24	  const middle = Math.floor(sorted.length / 2)
25	  return sorted.length % 2
26	    ? sorted[middle]
27	    : (sorted[middle - 1] + sorted[middle]) / 2
28	}
