30	function addIssue (report, severity, code, message, context = {}) {
31	  report.issues.push({ severity, code, message, ...context })
32	}
33	
34	function validateStages (manifest, report) {
35	  let lastTimestamp = Number(manifest.session?.startedAt) || 0
36	  for (const stage of manifest.stages || []) {
37	    const startedAt = Number(stage.startedAt) || 0
38	    const endedAt = Number(stage.endedAt) || 0
39	    if (startedAt < lastTimestamp) {
40	      addIssue(report, 'error', 'stage_time_non_monotonic',
41	        'Stage start time moves backwards.', { stageIndex: stage.index })
42	    }
43	    if (endedAt && endedAt < startedAt) {
44	      addIssue(report, 'error', 'stage_end_before_start',
45	        'Stage end time precedes its start.', { stageIndex: stage.index })
46	    }
47	    lastTimestamp = Math.max(lastTimestamp, startedAt, endedAt)
48	  }
49	}
50	
51	function validateEventSamples (event, report, seenSequences) {
52	  const samples = Array.isArray(event.samples) ? event.samples : []
53	  const intervals = []
54	  let previousTime = 0
55	  let previousSequence = -1
56	  let duplicateCount = 0
57	
58	  for (const sample of samples) {
59	    const timestamp = Number(sample.t)
60	    const sequence = Number(sample.seq)
61	    if (!Number.isFinite(timestamp) || !Number.isFinite(sequence)) {
62	      addIssue(report, 'error', 'invalid_sample',
63	        'Sample timestamp or sequence is not numeric.', { eventId: event.id })
64	      continue
65	    }
66	    if (previousTime && timestamp <= previousTime) {
67	      addIssue(report, 'error', 'sample_time_non_monotonic',
68	        'Sample timestamps are not strictly increasing.',
69	        { eventId: event.id, sequence })
70	    }
71	    if (previousSequence >= 0 && sequence <= previousSequence) {
72	      addIssue(report, 'error', 'sample_sequence_non_monotonic',
73	        'Sample sequences are not strictly increasing.',
74	        { eventId: event.id, sequence })
75	    }
76	    if (seenSequences.has(sequence)) duplicateCount += 1
77	    else seenSequences.add(sequence)
78	    if (previousTime && timestamp > previousTime) intervals.push(timestamp - previousTime)
79	    previousTime = timestamp
80	    previousSequence = sequence
81	  }
82	
83	  const medianIntervalMs = median(intervals)
84	  const meanIntervalMs = intervals.length
85	    ? intervals.reduce((sum, value) => sum + value, 0) / intervals.length
86	    : 0
87	  const sampleRateHz = medianIntervalMs > 0 ? 1000 / medianIntervalMs : 0
88	  const gapThresholdMs = Math.max(120, medianIntervalMs * 3)
89	  const gaps = intervals.filter((value) => value > gapThresholdMs)
90	
91	  if (samples.length < 2) {
92	    addIssue(report, 'warning', 'insufficient_samples',
93	      'Event has fewer than two samples.', { eventId: event.id })
94	  } else if (sampleRateHz < 35 || sampleRateHz > 65) {
95	    addIssue(report, 'warning', 'sample_rate_out_of_range',
96	      'Median event sample rate is outside the expected game interval range.',
97	      { eventId: event.id, sampleRateHz })
98	  }
99	  if (gaps.length) {
100	    addIssue(report, 'warning', 'sample_gap',
101	      'Event window contains one or more sensor gaps.',
102	      { eventId: event.id, gapCount: gaps.length, largestGapMs: Math.max(...gaps) })
103	  }
104	  return {
105	    eventId: event.id,
106	    sampleCount: samples.length,
107	    medianIntervalMs,
108	    meanIntervalMs: Math.round(meanIntervalMs * 1000) / 1000,
109	    sampleRateHz: Math.round(sampleRateHz * 1000) / 1000,
110	    gapCount: gaps.length,
111	    duplicateCount
112	  }
113	}
