115	export function mergeAndValidate (manifest, chunkRecords) {
116	  const report = {
117	    ok: true,
118	    formatVersion: manifest?.formatVersion,
119	    sessionId: manifest?.session?.id || '',
120	    summary: {
121	      manifestChunkCount: manifest?.chunks?.length || 0,
122	      suppliedChunkCount: chunkRecords.length,
123	      eventCount: 0,
124	      uniqueSampleCount: 0,
125	      duplicateSampleCount: 0,
126	      acceptedCount: 0,
127	      rejectedCount: 0
128	    },
129	    eventSampling: [],
130	    issues: []
131	  }
132	  const events = []
133	  const expectedReferences = new Map(
134	    (manifest?.chunks || []).map((reference) => [Number(reference.index), reference])
135	  )
136	  const seenChunkIndexes = new Set()
137	
138	  if (manifest?.formatVersion !== FORMAT_VERSION) {
139	    addIssue(report, 'error', 'manifest_format',
140	      `Expected manifest format ${FORMAT_VERSION}.`)
141	  }
142	  if (!manifest?.session?.id) {
143	    addIssue(report, 'error', 'missing_session_id', 'Manifest has no session ID.')
144	  }
145	  validateStages(manifest || {}, report)
146	
147	  const sortedChunks = chunkRecords.slice().sort((left, right) =>
148	    Number(left?.payload?.index) - Number(right?.payload?.index))
149	  for (const record of sortedChunks) {
150	    const payload = record?.payload
151	    const index = Number(payload?.index)
152	    if (!payload || payload.formatVersion !== FORMAT_VERSION) {
153	      addIssue(report, 'error', 'chunk_format', 'Chunk has an invalid format.', { index })
154	      continue
155	    }
156	    if (payload.sessionId !== report.sessionId) {
157	      addIssue(report, 'error', 'chunk_session',
158	        'Chunk belongs to a different session.', { index })
159	    }
160	    if (seenChunkIndexes.has(index)) {
161	      addIssue(report, 'error', 'duplicate_chunk', 'Chunk index is duplicated.', { index })
162	    }
163	    seenChunkIndexes.add(index)
164	    const actualChecksum = checksum(payload)
165	    if (record.checksum !== actualChecksum) {
166	      addIssue(report, 'error', 'chunk_checksum',
167	        'Chunk checksum does not match its payload.', { index })
168	    }
169	    const reference = expectedReferences.get(index)
170	    if (!reference) {
171	      addIssue(report, 'error', 'unexpected_chunk',
172	        'Chunk is not listed by the manifest.', { index })
173	    } else {
174	      if (reference.checksum !== record.checksum) {
175	        addIssue(report, 'error', 'manifest_checksum',
176	          'Manifest and chunk checksums differ.', { index })
177	      }
178	      if (Number(reference.eventCount) !== (payload.events || []).length) {
179	        addIssue(report, 'error', 'event_count',
180	          'Manifest event count differs from chunk payload.', { index })
181	      }
182	      if (Number(reference.serializedLength) !== JSON.stringify(record).length) {
183	        addIssue(report, 'error', 'serialized_length',
184	          'Manifest serialized length differs from chunk JSON.', { index })
185	      }
186	    }
187	    events.push(...(payload.events || []))
188	  }
189	
190	  for (const [index] of expectedReferences) {
191	    if (!seenChunkIndexes.has(index)) {
192	      addIssue(report, 'error', 'missing_chunk',
193	        'A manifest chunk was not supplied.', { index })
194	    }
195	  }
196	
197	  const seenEventIds = new Set()
198	  const seenSequences = new Set()
199	  for (const event of events) {
200	    if (seenEventIds.has(event.id)) {
201	      addIssue(report, 'error', 'duplicate_event',
202	        'Event ID is duplicated.', { eventId: event.id })
203	    }
204	    seenEventIds.add(event.id)
205	    if (Number(event.endedAt) < Number(event.startedAt)) {
206	      addIssue(report, 'error', 'event_time',
207	        'Event end time precedes its start.', { eventId: event.id })
208	    }
209	    if (typeof event.accepted !== 'boolean' || !event.reason) {
210	      addIssue(report, 'error', 'event_decision',
211	        'Event lacks accepted/rejected decision metadata.', { eventId: event.id })
212	    }
213	    if (!event.features || typeof event.qualityScore !== 'number') {
214	      addIssue(report, 'error', 'event_features',
215	        'Event lacks algorithm features or quality score.', { eventId: event.id })
216	    }
217	    const sampling = validateEventSamples(event, report, seenSequences)
218	    report.eventSampling.push(sampling)
219	    report.summary.duplicateSampleCount += sampling.duplicateCount
220	    if (event.accepted) report.summary.acceptedCount += 1
221	    else report.summary.rejectedCount += 1
222	  }
223	
224	  report.summary.eventCount = events.length
225	  report.summary.uniqueSampleCount = seenSequences.size
226	  if (report.summary.duplicateSampleCount) {
227	    addIssue(report, 'warning', 'overlapping_samples',
228	      'Sample sequences appear in multiple event windows; JSON uniqueSamples is deduplicated.',
229	      { duplicateCount: report.summary.duplicateSampleCount })
230	  }
231	  report.ok = !report.issues.some((issue) => issue.severity === 'error')
232	
233	  const uniqueSamples = []
234	  const outputSequences = new Set()
235	  for (const event of events) {
236	    for (const sample of event.samples || []) {
237	      if (!outputSequences.has(sample.seq)) {
238	        outputSequences.add(sample.seq)
239	        uniqueSamples.push(sample)
240	      }
241	    }
242	  }
243	  uniqueSamples.sort((left, right) => Number(left.seq) - Number(right.seq))
244	
245	  return {
246	    manifest,
247	    events,
248	    uniqueSamples,
249	    validation: report
250	  }
251	}
