253	export function readJson (file) {
254	  return JSON.parse(fs.readFileSync(file, 'utf8'))
255	}
256	
257	export function loadCapture (manifestFile, chunkFiles) {
258	  return mergeAndValidate(
259	    readJson(manifestFile),
260	    chunkFiles.map((file) => readJson(file))
261	  )
262	}
