264	function csvValue (value) {
265	  const text = value === undefined || value === null ? '' : String(value)
266	  return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text
267	}
268	
269	export function eventsToCsv (events) {
270	  const columns = [
271	    'session_id', 'event_id', 'stage_index', 'stage_name', 'accepted', 'reason',
272	    'event_started_at', 'event_ended_at', 'quality_score', 'sample_seq',
273	    'sample_timestamp', 'sample_dt_ms', 'x', 'y', 'z'
274	  ]
275	  const rows = [columns.join(',')]
276	  for (const event of events) {
277	    for (const sample of event.samples || []) {
278	      rows.push([
279	        event.id?.slice(0, event.id.lastIndexOf('-e')) || '',
280	        event.id,
281	        event.stageIndex,
282	        event.stageName,
283	        event.accepted,
284	        event.reason,
285	        event.startedAt,
286	        event.endedAt,
287	        event.qualityScore,
288	        sample.seq,
289	        sample.t,
290	        sample.dt,
291	        sample.x,
292	        sample.y,
293	        sample.z
294	      ].map(csvValue).join(','))
295	    }
296	  }
297	  return `${rows.join('\n')}\n`
298	}
299	
300	export function listChunkFiles (directory, manifestFile) {
301	  const manifestAbsolute = path.resolve(manifestFile)
302	  return fs.readdirSync(directory)
303	    .filter((name) => name.endsWith('.json'))
304	    .map((name) => path.join(directory, name))
305	    .filter((file) => path.resolve(file) !== manifestAbsolute)
306	    .sort()
307	}
