275	
276	  const FORMAT_VERSION = 'bmt-capture-v1'
277	  const ACTIVE_MANIFEST_KEY = 'bmt_capture_active_manifest_v1'
278	  const EXPORT_MANIFEST_KEY = 'bmt_capture_export_manifest_v1'
279	  const STAGE_NAMES = ['静止', '步行', '普通摆臂', '持拍回位', '过顶空挥', '实际击球']
280	  const DEFAULT_EXPECTED = [0, 0, 0, 5, 10, 10]
