282	  const RING_SAMPLES = 50
283	  const POST_WINDOW_MS = 1000
284	  const MAX_EVENTS_PER_CHUNK = 1
285	  const MAX_CHUNKS = 120
286	
287	  function clamp (value, min, max) {
288	    return Math.max(min, Math.min(max, Number(value) || 0))
289	  }
290	
291	  function round3 (value) {
292	    return Math.round((Number(value) || 0) * 1000) / 1000
293	  }
294	
295	  function checksum (text) {
296	    let hash = 2166136261
297	    for (let i = 0; i < text.length; i = i + 1) {
298	      hash = hash ^ text.charCodeAt(i)
