/*
 * Interconnect chunked export for BMT capture data.
 *
 * Sends manifest and chunk records to AstroBox via system.interconnect
 * in safe-length fragments. Each fragment is a self-contained JSON message
 * with session ID, content type, chunk index, fragment sequence, total
 * fragment count, data payload, and integrity checksum.
 *
 * Protocol: com.waylean.bmtsmash.capture.export v1
 */

var FRAGMENT_DATA_LIMIT = 400

function fnv1a32 (text) {
  var hash = 2166136261
  for (var i = 0; i < text.length; i = i + 1) {
    hash = hash ^ text.charCodeAt(i)
    hash = Math.imul(hash, 16777619)
  }
  return (hash >>> 0).toString(16).padStart(8, '0')
}

function toBase64 (text) {
  var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  var result = []
  var i = 0
  while (i < text.length) {
    var a = text.charCodeAt(i++)
    var b = i < text.length ? text.charCodeAt(i++) : 0
    var c = i < text.length ? text.charCodeAt(i++) : 0
    var triplet = (a << 16) | (b << 8) | c
    result.push(chars[(triplet >> 18) & 0x3f])
    result.push(chars[(triplight >> 12) & 0x3f])
    result.push(i > text.length + 1 ? '=' : chars[(triplet >> 6) & 0x3f])
    result.push(i > text.length ? '=' : chars[triplet & 0x3f])
  }
  return result.join('')
}

function fragmentJson (jsonText) {
  var fragments = []
  var offset = 0
  while (offset < jsonText.length) {
    fragments.push(jsonText.slice(offset, offset + FRAGMENT_DATA_LIMIT))
    offset = offset + FRAGMENT_DATA_LIMIT
  }
  if (fragments.length === 0) fragments.push('')
  return fragments
}

export function buildFragments (sessionId, category, index, record) {
  var jsonText = typeof record === 'string' ? record : JSON.stringify(record)
  var crc = fnv1a32(jsonText)
  var dataFragments = fragmentJson(jsonText)
  var total = dataFragments.length
  var messages = []
  for (var i = 0; i < total; i = i + 1) {
    messages.push(JSON.stringify({
      v: 1,
      sid: sessionId,
      cat: category,
      idx: index,
      frag: i,
      total: total,
      data: dataFragments[i],
      crc: crc
    }))
  }
  return messages
}

export function createInterconnectSender (interconnect) {
  var pending = []
  var sending = false
  var failed = false
  var failReason = ''

  function sendNext () {
    if (failed || pending.length === 0) {
      sending = false
      return
    }
    sending = true
    var item = pending[0]
    try {
      interconnect.send({
        data: item.message,
        success: function () {
          pending.shift()
          sendNext()
        },
        fail: function (msg, code) {
          failed = true
          failReason = 'interconnect_send_fail_' + code
          if (typeof item.fail === 'function') item.fail(failReason)
        }
      })
    } catch (err) {
      failed = true
      failReason = 'interconnect_send_exception'
      if (typeof item.fail === 'function') item.fail(failReason)
    }
  }

  function enqueue (message, fail) {
    pending.push({ message: message, fail: fail })
    if (!sending) sendNext()
  }

  return {
    available: Boolean(interconnect && typeof interconnect.send === 'function'),

    sendExport: function (sessionId, manifest, chunkRecords, onProgress, onDone) {
      if (!this.available) {
        if (typeof onDone === 'function') onDone('interconnect_unavailable')
        return
      }
      failed = false
      failReason = ''

      var allMessages = []

      var manifestFragments = buildFragments(sessionId, 'manifest', 0, manifest)
      for (var m = 0; m < manifestFragments.length; m = m + 1) {
        allMessages.push(manifestFragments[m])
      }

      for (var c = 0; c < chunkRecords.length; c = c + 1) {
        var chunkFragments = buildFragments(sessionId, 'chunk', c, chunkRecords[c])
        for (var f = 0; f < chunkFragments.length; f = f + 1) {
          allMessages.push(chunkFragments[f])
        }
      }

      var sent = 0
      var total = allMessages.length

      function sendOne (index) {
        if (failed) {
          if (typeof onDone === 'function') onDone(failReason)
          return
        }
        if (index >= total) {
          if (typeof onDone === 'function') onDone(null)
          return
        }
        enqueue(allMessages[index], function (err) {
          if (typeof onDone === 'function') onDone(err)
        })
        sent = sent + 1
        if (typeof onProgress === 'function') onProgress(sent, total)
        setTimeout(function () { sendOne(index + 1) }, 50)
      }

      sendOne(0)
    }
  }
}

